//! Parquet-to-Arrow type inference does not move across the 2026-10-24
//! upgrade. parquet 59 honours embedded Arrow schema hints that parquet 53
//! ignored (or crashed on); the source keeps parquet 53's types for files
//! written by pyarrow (`fixtures/hints/`, regenerated by
//! `fixtures/hints/generate.py`). The expected types below were captured by
//! reading the same files with parquet 53.4.1.

#![allow(clippy::unwrap_used, missing_docs)]

use std::path::PathBuf;

use arrow::array::{Array, Int64Array, TimestampNanosecondArray};
use arrow::datatypes::{DataType, TimeUnit};
use bellwether_source::{fingerprint, load_reader_metadata, ParquetSource};
use bellwether_types::Source;

fn hint_fixture(name: &str) -> String {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures/hints")
        .join(name);
    p.to_str().unwrap().to_string()
}

fn inferred(name: &str) -> Vec<(String, DataType)> {
    let file = std::fs::File::open(hint_fixture(name)).unwrap();
    let meta = load_reader_metadata(&file).unwrap();
    meta.schema()
        .fields()
        .iter()
        .map(|f| (f.name().clone(), f.data_type().clone()))
        .collect()
}

fn ns(tz: Option<&str>) -> DataType {
    DataType::Timestamp(TimeUnit::Nanosecond, tz.map(Into::into))
}

/// `dict_dur` carries a `Dictionary(Int32, Duration(ms))` hint: parquet 53
/// dropped a dictionary hint whose value hint did not apply, and read the
/// plain `Int64`.
#[test]
fn duration_hints_on_int64_columns_read_as_int64() {
    assert_eq!(
        inferred("duration.parquet"),
        [
            ("id".to_string(), DataType::Int64),
            ("dur_ms".to_string(), DataType::Int64),
            ("dur_s".to_string(), DataType::Int64),
            ("dict_dur".to_string(), DataType::Int64),
        ]
    );
}

#[test]
fn int96_timestamps_read_as_nanoseconds_as_parquet_53_did() {
    assert_eq!(
        inferred("int96.parquet"),
        [
            ("id".to_string(), DataType::Int64),
            ("ts96_us".to_string(), ns(None)),
            ("ts96_ms_utc".to_string(), ns(None)),
            ("ts96_ns_utc".to_string(), ns(Some("UTC"))),
            ("ts96_ns".to_string(), ns(None)),
        ]
    );
}

/// parquet 53 panicked inside arrow-ipc on a Decimal32 hint ("Unexpected
/// decimal bit width 32"); without the hint it read Decimal128, which is
/// what the source infers. A dictionary of Decimal32 (`dict_dec32`) follows
/// the same rule and reads as plain `Decimal128`.
#[test]
fn narrow_decimal_hints_read_as_decimal128() {
    assert_eq!(
        inferred("decimal.parquet"),
        [
            ("id".to_string(), DataType::Int64),
            ("dec32".to_string(), DataType::Decimal128(7, 2)),
            ("dec64".to_string(), DataType::Decimal128(15, 3)),
            ("dict_dec32".to_string(), DataType::Decimal128(7, 2)),
        ]
    );
}

/// The source reads, reports statistics for, and decodes those columns at
/// the restored types: the schema, the footer statistics, and the arrays
/// agree.
#[test]
fn the_source_decodes_at_the_restored_types() {
    let source = ParquetSource::new();
    let fp = fingerprint(&hint_fixture("duration.parquet")).unwrap();
    let rgs = source.row_groups(&fp).unwrap();
    assert_eq!(rgs.len(), 4);
    let dur = rgs[1].stats.iter().find(|s| s.column == "dur_ms").unwrap();
    assert!(dur.min.is_some() && dur.max.is_some(), "Int64 stats encode");
    let batch = source.read_columns(&rgs[1], &["dur_ms".into()]).unwrap();
    let col = batch
        .column(0)
        .as_any()
        .downcast_ref::<Int64Array>()
        .unwrap();
    assert_eq!(col.value(0), 10_000);
    let batch = source.read_columns(&rgs[0], &["dict_dur".into()]).unwrap();
    let col = batch
        .column(0)
        .as_any()
        .downcast_ref::<Int64Array>()
        .unwrap();
    assert_eq!(
        (0..4).map(|i| col.value(i)).collect::<Vec<_>>(),
        [0, 1000, 2000, 3000],
        "a dictionary of durations decodes as plain Int64"
    );

    let fp = fingerprint(&hint_fixture("int96.parquet")).unwrap();
    let rgs = source.row_groups(&fp).unwrap();
    let batch = source
        .read_columns(&rgs[0], &["ts96_us".into(), "ts96_ns_utc".into()])
        .unwrap();
    let us = batch
        .column(0)
        .as_any()
        .downcast_ref::<TimestampNanosecondArray>()
        .unwrap();
    assert_eq!(us.value(1), 1_700_000_000_000_001_000);
    assert_eq!(us.timezone(), None);
    assert_eq!(batch.column(1).data_type(), &ns(Some("UTC")));
}
